// Tiger Data (Postgres + TimescaleDB), schema owned by Lane C. The agent writes:
//   events           every event it emits
//   org_edges        the live org map (upserts; learned rows carry learned_from)
//   requests         live requests, origin = 'agent'           ─┐ what Insights reads
//                    (hr_sensitive is generated by C from task_type)
//   request_hops     who was asked, and how each hop ended     ─┘ (hours saved, bottlenecks)
// requests / request_hops are projected from the event stream in project() below,
// so the agents themselves know nothing about Tiger.
//
// Writes go through one queue (rows reference each other) and never block a
// conversation. TIGER_DISABLED=1 (sims, tests) keeps everything local.

import pg from "pg";
import type { Event, OrgEdge } from "@wayfinder/shared";
import { env } from "../env.ts";

let pool: pg.Pool | undefined;
let ready: Promise<boolean> | undefined;
let queue: Promise<unknown> = Promise.resolve();

export const tigerConfigured = () =>
  Boolean(env.tiger.url && env.tiger.password) && process.env.TIGER_DISABLED !== "1";

function getPool(): pg.Pool {
  if (pool) return pool;
  const url = new URL(env.tiger.url);
  url.searchParams.delete("sslmode"); // TLS is configured below
  // pg lets the connection string override a separate `password` option, so it goes in the URL.
  if (env.tiger.password) url.password = encodeURIComponent(env.tiger.password);
  pool = new pg.Pool({
    connectionString: url.toString(),
    ssl: { rejectUnauthorized: !env.tiger.insecureTls },
    max: 4,
    connectionTimeoutMillis: 8000,
  });
  pool.on("error", (err) => console.warn(`[tiger] ${err.message}`));
  return pool;
}

/** True once we know Tiger is reachable and Lane C's tables exist. */
export function tigerReady(): Promise<boolean> {
  ready ??= (async () => {
    if (!tigerConfigured()) return false;
    try {
      const { rows } = await getPool().query(
        `select bool_and(to_regclass(t) is not null) as ok from unnest(array['events','org_edges','requests','request_hops']) t`,
      );
      if (!rows[0].ok) {
        console.warn("[tiger] connected, but Lane C's tables are missing. Logging locally.");
        return false;
      }
      return true;
    } catch (err) {
      console.warn(`[tiger] unavailable, logging locally: ${err instanceof Error ? err.message : err}`);
      return false;
    }
  })();
  return ready;
}

/** Run writes in order, after Tiger is known to be ready; failures are logged, never thrown. */
function enqueue(write: (db: pg.Pool) => Promise<unknown>) {
  queue = queue.then(async () => {
    if (!(await tigerReady())) return;
    try {
      await write(getPool());
    } catch (err) {
      console.warn(`[tiger] write failed: ${err instanceof Error ? err.message : err}`);
    }
  });
}

/** Resolves once every queued write has been attempted (scripts and tests). */
export const tigerFlushed = () => queue;

// ── events ─────────────────────────────────────────────────────────────────

export function writeEvent(e: Event) {
  enqueue((db) =>
    db.query(
      `insert into events (id, ts, type, actor, request_id, tool, payload) values ($1,$2,$3,$4,$5,$6,$7) on conflict do nothing`,
      [e.id, e.ts, e.type, e.actor, e.request_id ?? null, e.tool ?? null, JSON.stringify(e.payload)],
    ),
  );
  project(e);
}

// ── org map ────────────────────────────────────────────────────────────────

const UPSERT_EDGE = `insert into org_edges (from_id, to_id, task_type, confidence, source, delegate_until, learned_from)
  values ($1,$2,$3,$4,$5,$6,$7)
  on conflict (from_id, to_id, task_type) do update
    set confidence = excluded.confidence, source = excluded.source, delegate_until = excluded.delegate_until,
        learned_from = coalesce(excluded.learned_from, org_edges.learned_from), updated_at = now()`;

const edgeArgs = (e: OrgEdge, learnedFrom?: string) => [
  e.from, e.to, e.task_type, e.confidence, e.source, e.delegate_until ?? null, learnedFrom ?? null,
];

export function writeEdge(e: OrgEdge, learnedFrom?: string) {
  enqueue((db) => db.query(UPSERT_EDGE, edgeArgs(e, learnedFrom)));
}

/** /reset: drop what the agent learned and put the chart's confidences back. */
export function resetEdges(chart: OrgEdge[]) {
  enqueue(async (db) => {
    await db.query(`delete from org_edges where source = 'learned'`);
    for (const e of chart) await db.query(UPSERT_EDGE, edgeArgs(e));
  });
}

/** The org map as stored in Tiger, or undefined when Tiger isn't ready or is empty. */
export async function readEdges(): Promise<OrgEdge[] | undefined> {
  if (!(await tigerReady())) return undefined;
  const { rows } = await getPool().query(
    `select from_id, to_id, task_type, confidence, source, delegate_until from org_edges`,
  );
  if (rows.length === 0) return undefined;
  return rows.map((r) => ({
    from: r.from_id,
    to: r.to_id,
    task_type: r.task_type,
    confidence: Number(r.confidence),
    source: r.source,
    ...(r.delegate_until && { delegate_until: new Date(r.delegate_until).toISOString() }),
  }));
}

// ── requests / request_hops (projected from events) ─────────────────────────

const isActor = (id: unknown): id is string => typeof id === "string" && /^(p_|dept_)/.test(id);

/** Next hop starts from whoever held it last, or the requester for the first hop. */
const OPEN_HOP = `insert into request_hops (request_id, seq, from_id, to_id, at, outcome, note)
  select $1,
         coalesce((select max(seq) from request_hops where request_id = $1), 0) + 1,
         coalesce((select to_id from request_hops where request_id = $1 order by seq desc, at desc limit 1),
                  (select requester_id from requests where id = $1)),
         $2, $3, 'pending', $4
  where exists (select 1 from requests where id = $1)`;

/** Close the pending hop to `holder` (or the latest pending one if they weren't the one asked). */
const CLOSE_HOP = `update request_hops set outcome = $3, redirect_to = $4, note = coalesce($5, note)
  where (request_id, seq, at) = (
    select request_id, seq, at from request_hops
    where request_id = $1 and outcome = 'pending'
    order by (to_id = $2) desc, seq desc limit 1)`;

function project(e: Event) {
  const id = e.request_id;
  if (!id?.startsWith("req_live_")) return;
  const p = e.payload as Record<string, unknown>;
  const closeHop = (holder: unknown, outcome: string, redirectTo?: unknown, note?: unknown) =>
    enqueue((db) =>
      db.query(CLOSE_HOP, [id, holder ?? null, outcome, isActor(redirectTo) ? redirectTo : null, typeof note === "string" ? note : null]),
    );
  const openHop = (to: unknown, note?: string) => {
    if (isActor(to)) enqueue((db) => db.query(OPEN_HOP, [id, to, e.ts, note ?? null]));
  };

  switch (e.type) {
    case "request_created":
      enqueue((db) =>
        db.query(
          // hr_sensitive is a generated column in C's schema (derived from task_type)
          `insert into requests (id, task_type, title, requester_id, created_at, status, amount_usd, origin)
           values ($1,$2,$3,$4,$5,'open',$6,'agent') on conflict (id) do nothing`,
          [id, p.task_type ?? "other", p.title ?? p.goal ?? id, e.actor, e.ts, p.amount_usd ?? null],
        ),
      );
      break;
    case "routed":
      openHop(p.owner ?? (p.chain as string[] | undefined)?.at(-1), `${p.kind ?? "action"} ${p.step ?? ""}`.trim());
      break;
    case "approval_requested":
      openHop(p.approver, `approval $${p.amount_usd}`);
      break;
    case "step_done":
      closeHop(p.by, "handled");
      break;
    case "approved":
      closeHop(p.approver, "handled", undefined, "approved");
      break;
    case "denied":
      closeHop(p.approver ?? p.by, "handled", undefined, `denied${p.note ? `: ${p.note}` : ""}`);
      break;
    case "redirected":
      closeHop(p.by, "bounced", p.to, "not ours");
      break;
    case "delegated":
      closeHop(p.from, "delegated", p.to);
      break;
    case "escalated":
      closeHop(p.from, "forwarded", p.to, "no reply, escalated");
      break;
    case "request_resolved": {
      const owners = ((p.steps as { owner?: string }[] | undefined) ?? []).map((s) => s.owner).filter(isActor);
      enqueue((db) =>
        db.query(
          `update requests set status = 'resolved', resolved_at = $2, resolved_by = $3, resolution = $4 where id = $1`,
          [id, e.ts, owners.at(-1) ?? null, String(p.title ?? "Resolved by Wayfinder")],
        ),
      );
      break;
    }
    case "request_denied":
    case "request_stuck":
      enqueue((db) => db.query(`update requests set resolution = $2 where id = $1`, [id, e.type.replace("request_", "")]));
      break;
  }
}

export async function closeTiger() {
  await queue;
  await pool?.end();
}
